// Native checks of wave J13, bigger main waveforms (spec 2h):
// mixxx-waveform-height.patch with real Qt widgets and real Mixxx controls.
//
// usage: waveform-height-test SKIN_XML MODE
// SKIN_XML is a skin generated by mixpi-performance.py (MODE "focus" or
// "overlay", its --loop-display). The fixture builds the skin's widget tree
// (each WidgetGroup and WidgetStack a QWidget with the skin's ObjectName,
// each Visual a viewer QWidget in it, as LegacySkinParser parents them) and
// asks the patch which viewers are main waveforms, as
// WaveformWidgetFactory::createWaveformWidget does. It then draws synthetic
// waveform data at known levels with the gain each viewer's
// WaveformWidgetRenderer takes (mixpi::waveformHeightGain on the real
// [ChannelN],pregain and [ChannelN],total_gain controls) and the height
// formula of the all-shader RGB renderer:
//   height = gain x VisualGain_0 x halfBreadth / 255 x filtered.all
// Built with MIXPI_WAVEFORM_HEIGHT_BASELINE (the stack without the patch),
// every viewer takes total_gain, as stock Mixxx does, and the checks about
// the main waveforms fail.
// Wave J15 (mixxx-waveform-height-gain.patch): a main waveform's gain is the
// pregain knob x MIXPI_EXPECTED_MAIN_GAIN (0.80, given by the runner, not
// read from the patch), so its checks fail on the stack without that patch.
#include <QApplication>
#include <QDomDocument>
#include <QFile>
#include <QStringList>
#include <QWidget>
#include <cmath>
#include <cstdio>
#include <memory>
#include <vector>

#include "control/controlobject.h"
#include "control/controlproxy.h"
#ifndef MIXPI_WAVEFORM_HEIGHT_BASELINE
#include "waveform/mixpiwaveformgain.h"
#else
// Stock Mixxx: no viewer is told apart, and m_gain is total_gain.
namespace mixpi {
inline bool isMainWaveform(const QWidget*) {
    return false;
}
inline double waveformHeightGain(bool, double, double totalGain) {
    return totalGain;
}
} // namespace mixpi
#endif

#ifndef MIXPI_EXPECTED_MAIN_GAIN
#error "MIXPI_EXPECTED_MAIN_GAIN (the main waveforms' gain) is required"
#endif

namespace {
int failures = 0;

// The owner's gain for the decks' main waveforms (wave J15).
constexpr double kMainGain = MIXPI_EXPECTED_MAIN_GAIN;

// WaveformWidgetFactory's default VisualGain_0, as on the card.
constexpr double kVisualGain = 1.0;
// Half of a 128 px main waveform row.
constexpr double kHalfBreadth = 64.0;
// Synthetic filtered.all levels (0-255) and a track's ReplayGain of
// -8.5 dB (the card's median).
const std::vector<int> kLevels{64, 128, 200, 255};
constexpr double kReplayGain = 0.377;
constexpr double kDefaultBoost = 0.501187; // InitialDefaultBoost -6 dB

void check(bool ok, const QString& name) {
    std::printf("%s %s\n", ok ? "PASS" : "FAIL", qPrintable(name));
    std::fflush(stdout);
    if (!ok) {
        std::fprintf(stderr, "FAIL %s\n", qPrintable(name));
        ++failures;
    }
}

bool near(double a, double b) {
    return std::fabs(a - b) < 1e-6;
}

struct Viewer {
    QWidget* pWidget;
    int channel;
    QString path;
    bool main;
};

QString childText(const QDomElement& element, const QString& name) {
    return element.firstChildElement(name).text().trimmed();
}

// LegacySkinParser: a group's children are made with the group as parent,
// after the group's ObjectName is set.
void build(const QDomElement& element, QWidget* pParent, const QString& path,
        std::vector<Viewer>* pViewers) {
    for (QDomElement child = element.firstChildElement(); !child.isNull();
            child = child.nextSiblingElement()) {
        const QString tag = child.tagName();
        if (tag == QStringLiteral("WidgetGroup") || tag == QStringLiteral("WidgetStack")) {
            auto* pGroup = new QWidget(pParent);
            pGroup->setObjectName(childText(child, QStringLiteral("ObjectName")));
            const QString groupPath = path + QStringLiteral("/") + pGroup->objectName();
            build(child.firstChildElement(QStringLiteral("Children")), pGroup, groupPath, pViewers);
        } else if (tag == QStringLiteral("Visual")) {
            auto* pViewer = new QWidget(pParent);
            pViewer->setObjectName(childText(child, QStringLiteral("ObjectName")));
            const int channel = childText(child, QStringLiteral("Channel")).toInt();
            pViewers->push_back(Viewer{pViewer, channel, path, mixpi::isMainWaveform(pViewer)});
        } else if (tag == QStringLiteral("Children") || tag == QStringLiteral("skin")) {
            build(child, pParent, path, pViewers);
        }
    }
}

double height(const Viewer& viewer, int level, ControlProxy* pPregain, ControlProxy* pTotal) {
    const double gain = mixpi::waveformHeightGain(viewer.main, pPregain->get(), pTotal->get());
    return gain * kVisualGain * kHalfBreadth / 255.0 * level;
}

QString heights(const Viewer& viewer, ControlProxy* pPregain, ControlProxy* pTotal) {
    QStringList parts;
    for (int level : kLevels) {
        parts << QString::number(height(viewer, level, pPregain, pTotal), 'f', 2);
    }
    return parts.join(QStringLiteral(" "));
}

bool heightsAre(const Viewer& viewer, double gain, ControlProxy* pPregain, ControlProxy* pTotal) {
    for (int level : kLevels) {
        if (!near(height(viewer, level, pPregain, pTotal),
                    gain * kVisualGain * kHalfBreadth / 255.0 * level)) {
            return false;
        }
    }
    return true;
}
} // namespace

int main(int argc, char** argv) {
    QApplication app(argc, argv);
    if (argc != 3) {
        std::fprintf(stderr, "usage: waveform-height-test SKIN_XML focus|overlay\n");
        return 2;
    }
    const QString mode = QString::fromLocal8Bit(argv[2]);
    QFile file(QString::fromLocal8Bit(argv[1]));
    QDomDocument document;
    if (!file.open(QIODevice::ReadOnly) || !document.setContent(&file)) {
        std::fprintf(stderr, "cannot read %s\n", argv[1]);
        return 2;
    }

    // EnginePregain's controls for the two decks.
    std::vector<std::unique_ptr<ControlObject>> controls;
    for (const char* group : {"[Channel1]", "[Channel2]"}) {
        controls.push_back(std::make_unique<ControlObject>(ConfigKey(group, "pregain")));
        controls.push_back(std::make_unique<ControlObject>(ConfigKey(group, "total_gain")));
    }

    QWidget root;
    root.setObjectName(QStringLiteral("Mixxx"));
    std::vector<Viewer> viewers;
    build(document.documentElement(), &root, QString(), &viewers);
    for (const Viewer& viewer : viewers) {
        std::printf("VIEWER %s channel %d main %d in %s\n", qPrintable(mode), viewer.channel,
                viewer.main ? 1 : 0, qPrintable(viewer.path));
    }

    std::vector<const Viewer*> decks;
    std::vector<const Viewer*> loopPanel;
    for (const Viewer& viewer : viewers) {
        if (viewer.path.contains(QStringLiteral("/MixpiWaveforms/"))) {
            decks.push_back(&viewer);
        } else {
            loopPanel.push_back(&viewer);
        }
    }
    check(decks.size() == 2 && decks[0]->channel == 1 && decks[1]->channel == 2,
            QStringLiteral("%1: the Decks page has one main waveform per deck").arg(mode));
    check(loopPanel.size() == (mode == QStringLiteral("focus") ? 2u : 0u),
            QStringLiteral("%1: the Loop panel's waveforms are separate viewers (%2)")
                    .arg(mode)
                    .arg(mode == QStringLiteral("focus") ? 2 : 0));
    bool decksMain = !decks.empty();
    for (const Viewer* viewer : decks) {
        decksMain = decksMain && viewer->main;
    }
    check(decksMain, QStringLiteral("%1: both main waveforms are told apart as main").arg(mode));
    bool loopNotMain = true;
    for (const Viewer* viewer : loopPanel) {
        loopNotMain = loopNotMain && !viewer->main;
    }
    check(loopNotMain, QStringLiteral("%1: the Loop panel's waveforms are not main").arg(mode));

    for (int channel = 1; channel <= 2; ++channel) {
        const QString group = QStringLiteral("[Channel%1]").arg(channel);
        ControlProxy pregain(group, QStringLiteral("pregain"));
        ControlProxy total(group, QStringLiteral("total_gain"));
        const Viewer* deck = nullptr;
        for (const Viewer* viewer : decks) {
            if (viewer->channel == channel) {
                deck = viewer;
            }
        }
        if (!deck) {
            continue;
        }
        const Viewer* loop = nullptr;
        for (const Viewer* viewer : loopPanel) {
            if (viewer->channel == channel) {
                loop = viewer;
            }
        }

        // A track with ReplayGain -8.5 dB, pregain knob at 0 dB.
        pregain.set(1.0);
        total.set(1.0 * kReplayGain);
        std::printf("HEIGHTS %s deck %d rg %.3f pregain 1 main: %s\n", qPrintable(mode), channel,
                kReplayGain, qPrintable(heights(*deck, &pregain, &total)));
        check(heightsAre(*deck, 1.0 * kMainGain, &pregain, &total),
                QStringLiteral("%1 deck %2: the main waveform's height is pregain x "
                               "VisualGain_0 x %3 x halfBreadth / 255 x level (ReplayGain left out)")
                        .arg(mode)
                        .arg(channel)
                        .arg(kMainGain, 0, 'f', 2));
        check(near(height(*deck, 255, &pregain, &total), kMainGain * kHalfBreadth) &&
                        height(*deck, 255, &pregain, &total) < kHalfBreadth,
                QStringLiteral("%1 deck %2: a level of 255 stops at %3 of the half height, "
                               "short of the edge")
                        .arg(mode)
                        .arg(channel)
                        .arg(kMainGain, 0, 'f', 2));
        if (loop) {
            std::printf("HEIGHTS %s deck %d rg %.3f pregain 1 loop panel: %s\n", qPrintable(mode),
                    channel, kReplayGain, qPrintable(heights(*loop, &pregain, &total)));
            check(heightsAre(*loop, kReplayGain, &pregain, &total),
                    QStringLiteral("%1 deck %2: the Loop panel's waveform still follows total_gain")
                            .arg(mode)
                            .arg(channel));
        }

        // The pregain knob at +6 dB still scales the main waveform.
        pregain.set(2.0);
        total.set(2.0 * kReplayGain);
        std::printf("HEIGHTS %s deck %d rg %.3f pregain 2 main: %s\n", qPrintable(mode), channel,
                kReplayGain, qPrintable(heights(*deck, &pregain, &total)));
        check(heightsAre(*deck, 2.0 * kMainGain, &pregain, &total),
                QStringLiteral("%1 deck %2: the pregain knob still scales the main waveform (x2)")
                        .arg(mode)
                        .arg(channel));
        if (loop) {
            check(heightsAre(*loop, 2.0 * kReplayGain, &pregain, &total),
                    QStringLiteral("%1 deck %2: the pregain knob still scales the Loop panel's "
                                   "waveform (x2)")
                            .arg(mode)
                            .arg(channel));
        }

        // The pregain knob at -6 dB.
        pregain.set(0.5);
        total.set(0.5 * kReplayGain);
        check(heightsAre(*deck, 0.5 * kMainGain, &pregain, &total),
                QStringLiteral("%1 deck %2: the pregain knob still scales the main waveform (x0.5)")
                        .arg(mode)
                        .arg(channel));

        // A track with no ReplayGain yet: Mixxx's -6 dB default boost.
        pregain.set(1.0);
        total.set(kDefaultBoost);
        check(heightsAre(*deck, 1.0 * kMainGain, &pregain, &total),
                QStringLiteral("%1 deck %2: a track with no ReplayGain is drawn at %3 of its "
                               "stored level")
                        .arg(mode)
                        .arg(channel)
                        .arg(kMainGain, 0, 'f', 2));
        if (loop) {
            check(heightsAre(*loop, kDefaultBoost, &pregain, &total),
                    QStringLiteral("%1 deck %2: the Loop panel's waveform keeps the default boost")
                            .arg(mode)
                            .arg(channel));
        }
    }

    std::printf("RESULT %s %s\n", qPrintable(mode), failures ? "FAIL" : "PASS");
    return failures ? 1 : 0;
}
